/** Linha de contacto das páginas de informação, na língua escolhida. */
function contactLineIn(lang: Lang, email?: string | null): string {
  if (lang === "pt") return contactLine(email);
  const e = (email ?? "").trim();
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
  if (lang === "en") return ok ? `You can contact us by email at ${e}.` : "You can contact us through your account (Account → Help) or by reporting the content concerned.";
  return ok ? `您可以发送邮件至 ${e} 联系我们。` : "您可以通过您的账户（账户 → 帮助）或举报相关内容联系我们。";
}

/** «Devoluções e reembolsos» na língua escolhida (o português vem do core). */
export function returnsPageIn(lang: Lang, email?: string | null): InfoPage {
  const base = returnsPage(email);
  if (lang === "pt") return base;
  const c = contactLineIn(lang, email);
  if (lang === "en") return { ...base, title: "Returns and refunds",
    intro: "How to request a return, refund or exchange for an order placed in the Huambo Online Shop, and what happens at each step.",
    sections: [
      { title: "Listings: the item must match the listing", paragraphs: [
        "Whoever posts a listing declares that the description, photos and price match the item, including defects.",
        "If you bought or rented and the item has a hidden defect, is different from the description, is another item or has missing parts, open the listing and tap “The item does not match the listing” (up to 7 days after the deal).",
        "Choose what you want: exchange, return and refund, or refund. The owner has 3 days to reply; if they refuse or don't reply, ask the administration to decide. Complaints appear on this page."] },
      { title: "1. When can I request", paragraphs: [
        "For a Shop order you have already paid for or received, up to 14 days after delivery.",
        "Reasons: not received, arrived damaged or broken, different from the listing, wrong item (model, size, colour) or missing items.",
        "If the order is still “Pending”, you don't need a request: tap “Cancel”."] },
      { title: "2. What can I request", paragraphs: [
        "Refund: the seller gives you back the money (all or part).",
        "Return and refund: you return the item to the seller and they give you back the money.",
        "Exchange: the seller sends you another identical item in good condition."] },
      { title: "3. How to request", paragraphs: [
        "Open “Orders”, choose the order and tap “Request a return or refund”.",
        "Choose the reason, explain what happened and attach up to 4 photos. The photos stay private: only the seller and the administration see them.",
        "Follow everything in “Returns and refunds”. Each step sends a notification to the other person."] },
      { title: "4. What the seller does", paragraphs: [
        "Accepts the request or declines it, explaining why.",
        "If they accept a return, agree via messages where to hand over the item. When they receive it, they confirm and refund the money.",
        "When they refund the money, they tap “I have refunded the money” and the buyer confirms receipt."] },
      { title: "5. If you can't agree", paragraphs: [
        "If the seller declines, you can call the administration straight away. If someone doesn't reply within 3 days, either of you can call the administration.",
        "The administration looks at the request, the messages and the photos, and decides: refund (all or part), return, exchange or refusal. The decision is recorded.",
        "Anyone who does not comply with a decision may have their account suspended."] },
      { title: "6. Paid and cancelled order", paragraphs: [
        "If the order was already paid and was cancelled, the refund request opens automatically: the seller must refund the full amount.",
        "With protected payment, Huambo Online refunds the money it still holds: enter your IBAN or Multicaixa Express number in the request."] },
      { title: "7. How the money arrives", paragraphs: [
        "For purchases paid to the seller (on delivery, bank transfer or Multicaixa Express), Huambo Online does not hold the money: the refund is made by the seller, using the same payment method, unless the two agree otherwise.",
        "For purchases with protected payment, Huambo Online holds the money until receipt is confirmed. While it is held, the refund is made by Huambo Online. After it has been released to the seller, the seller makes the refund.",
        "Keep your payment and refund receipts: the administration may ask for them."] },
      { title: "8. Deals outside the Shop", paragraphs: [
        "In classified listings (sale, swap, rental) the deal is made directly between people, but the conformity guarantee applies: if the item does not match the listing, use “The item does not match the listing” on the listing page (see above). For other problems, use “Report” and the administration will review it."] },
      { title: "9. Contact", paragraphs: [c] }
    ] };
  return { ...base, title: "退货与退款",
    intro: "如何为在 Huambo Online 商店下的订单申请退货、退款或换货，以及每一步会发生什么。",
    sections: [
      { title: "分类信息：物品必须与描述相符", paragraphs: [
        "发布信息的人声明描述、照片和价格与物品相符，包括瑕疵。",
        "如果您购买或租用的物品有隐藏缺陷、与描述不符、不是同一件物品或缺少零件，请打开该信息并点击“物品与信息不符”（交易后 7 天内）。",
        "选择您的诉求：换货、退货退款或仅退款。物主有 3 天时间回复；如果拒绝或未回复，请让管理员裁决。投诉会显示在此页面。"] },
      { title: "1. 何时可以申请", paragraphs: [
        "对于已付款或已收货的商店订单，可在送达后 14 天内申请。",
        "原因：未收到、到货时损坏或破碎、与描述不符、发错商品（型号、尺寸、颜色）或缺少商品。",
        "如果订单仍为“待处理”，无需申请：直接点击“取消”。"] },
      { title: "2. 可以申请什么", paragraphs: [
        "退款：卖家退还您的钱（全部或部分）。",
        "退货退款：您将商品退还给卖家，卖家退还您的钱。",
        "换货：卖家给您寄送另一件完好的相同商品。"] },
      { title: "3. 如何申请", paragraphs: [
        "打开“订单”，选择订单并点击“申请退货或退款”。",
        "选择原因，说明发生了什么，并附上最多 4 张照片。照片保密：只有卖家和管理员可以查看。",
        "在“退货与退款”中跟进全部进度。每一步都会通知对方。"] },
      { title: "4. 卖家要做什么", paragraphs: [
        "接受申请，或说明理由后拒绝。",
        "如果接受退货，双方通过消息商定交还商品的地点。卖家收到商品后确认并退款。",
        "退款后，卖家点击“我已退款”，由买家确认收到。"] },
      { title: "5. 如果双方无法达成一致", paragraphs: [
        "如果卖家拒绝，您可以立即请管理员介入。如果有一方 3 天内未回复，任何一方都可以请管理员介入。",
        "管理员会查看申请、消息和照片，并作出裁决：退款（全部或部分）、退货、换货或驳回。裁决会被记录。",
        "不遵守裁决的人可能会被暂停账户。"] },
      { title: "6. 已付款并取消的订单", paragraphs: [
        "如果订单已付款后被取消，退款申请会自动发起：卖家必须全额退款。",
        "使用担保支付时，仍在代管中的款项由 Huambo Online 退还：请在申请中填写您的 IBAN 或 Multicaixa Express 号码。"] },
      { title: "7. 退款如何到账", paragraphs: [
        "对于直接付给卖家的购买（货到付款、银行转账或 Multicaixa Express），Huambo Online 不代管款项：退款由卖家通过相同的支付方式进行，除非双方另有约定。",
        "对于使用担保支付的购买，款项由 Huambo Online 代管，直到确认收货。代管期间由 Huambo Online 退款；款项转给卖家后，由卖家退款。",
        "请保留付款和退款凭证：管理员可能会要求提供。"] },
      { title: "8. 商店以外的交易", paragraphs: [
        "在分类信息（出售、交换、租赁）中，交易直接在个人之间进行，但适用相符保证：如果物品与信息不符，请在信息页面使用“物品与信息不符”（见上文）。其他问题请使用“举报”，管理员会进行审核。"] },
      { title: "9. 联系方式", paragraphs: [c] }
    ] };
}

/** «Como apagar a minha conta» na língua escolhida (o português vem do core). */
export function deleteAccountPageIn(lang: Lang, email?: string | null): InfoPage {
  const base = deleteAccountPage(email);
  if (lang === "pt") return base;
  const c = contactLineIn(lang, email);
  if (lang === "en") return { ...base, title: "How to delete my account",
    intro: "You can delete your Huambo Online account at any time, on the Website or in the APP.",
    sections: [
      { title: "Steps", paragraphs: [
        "1. Sign in to your account (Website or APP).",
        "2. Open “Your account”.",
        "3. At the end of the page, under “Delete account”, type ELIMINAR and confirm."] },
      { title: "What is deleted", paragraphs: [
        "The account, profile, listings, products, saved items, saved searches, notifications and the data linked to the account.",
        "Reviews you left for other people and messages already sent may be deleted or remain without your name."] },
      { title: "Can't sign in?", paragraphs: [
        "Use “I forgot my password” on the sign-in page to recover access and then delete the account.", c] }
    ] };
  return { ...base, title: "如何删除我的账户",
    intro: "您可以随时在网站或 APP 上删除您的 Huambo Online 账户。",
    sections: [
      { title: "步骤", paragraphs: [
        "1. 登录您的账户（网站或 APP）。",
        "2. 打开“您的账户”。",
        "3. 在页面底部的“删除账户”中输入 ELIMINAR 并确认。"] },
      { title: "会删除哪些内容", paragraphs: [
        "账户、个人资料、信息、商品、收藏、保存的搜索、通知以及与账户相关的数据。",
        "您给他人留下的评价和已发送的消息可能会被删除，或保留但不显示您的名字。"] },
      { title: "无法登录？", paragraphs: [
        "在登录页面使用“忘记密码”恢复访问，然后删除账户。", c] }
    ] };
}
